import csv
import statistics

FILE = "gradebook.csv"

def save_scores(scores):
    with open(FILE, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["student", "score"])
        for name, score in scores.items():
            writer.writerow([name, score])

def load_scores():
    scores = {}
    try:
        with open(FILE, newline="") as f:
            for row in csv.DictReader(f):
                scores[row["student"]] = int(row["score"])
    except FileNotFoundError:
        pass
    return scores

def grade(score):
    if score >= 70:
        return "A"
    elif score >= 55:
        return "B"
    elif score >= 40:
        return "C"
    return "F"

def report(scores):
    print(f"{'Student':<10}{'Score':>6}  Grade")
    for name, score in sorted(scores.items()):
        print(f"{name:<10}{score:>6}  {grade(score)}")
    values = list(scores.values())
    print(f"Average: {statistics.mean(values):.1f}")
    print(f"Highest: {max(scores, key=scores.get)} ({max(values)})")

scores = load_scores()
print("Loaded", len(scores), "students")
scores["Ama"] = 72
scores["Kofi"] = 58
scores["Zainab"] = 91
scores["Wanjiru"] = 35
save_scores(scores)
report(load_scores())

